import{_ as l,l as o,o as e,c,v as s,p as i,x as r,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"分配器内部结构","description":"","frontmatter":{"title":"分配器内部结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/allocator-structures.md","filePath":"cs/allocator-structures.md","lastUpdated":1789023840000}'),u={name:"cs/allocator-structures.md"};function h(m,a,_,f,b,E){const t=o("Mermaid");return e(),c("div",null,[a[1]||(a[1]=s('<h1 id="分配器内部结构" tabindex="-1">分配器内部结构 <a class="header-anchor" href="#分配器内部结构" aria-label="Permalink to &quot;分配器内部结构&quot;">​</a></h1><div class="epigraph"><p>空闲块用隐式边界标签、显式空闲链、或按 size class 的 slab；分配器是数据结构，不是魔法系统调用。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Wilson, Johnstone, Neely and Boles, Dynamic Storage Allocation: A Survey and Critical Review, IWMM 1995；[buddy 分配器](/cs/buddy-allocator) 整理</footer></div><p><a href="/cs/rcu-data-structures">上一课</a> 延迟 <code>free</code>，块回到分配器。<a href="/cs/buddy-allocator">buddy</a> 已给页框。<a href="/cs/array-random-access">数组</a> 是用户对象布局。本课不 synchronize_rcu。缺口是用户级堆：边界标签、空闲双向链表、分离空闲表、slab/size class。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>malloc(n)</code> / <code>free(p)</code> 要 \\(\\Theta(1)\\) 或对数找块，减少碎片。隐式：块头存 size 与 busy 位，空闲靠扫描（首次适应）。显式：空闲块内嵌指针成链或树（按大小的 BST/Treap）。分离：每个 size class 一条链，小对象 O(1)。slab：同尺寸对象槽位图或空闲栈。缺口是<strong>把堆管理写成这些结构的组合</strong>，而不是「向 OS 要页」一句。</p><p><span class="marginnote">Knuth 边界标签。Wilson et al. 1995 综述适应策略与碎片。页仍可用 mmap/brk；本课内部。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配：size class 上 pop；没有则向更粗粒度要（buddy 页或新 span）。释放：压回 class，或合并相邻空闲（边界标签看前后块 busy）。线程缓存：每线程 magazine 减锁，耗尽再碰中心堆——并发哈希课的分段思想同构。</p>',8)),(e(),i(p,null,{default:r(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MALLOC%5B%22malloc%20n%22%5D%20--%3E%20SC%5B%22size%20class%20%E7%A9%BA%E9%97%B2%E6%A0%88%22%5D%0A%20%20SC%20--%3E%20SPAN%5B%22%E6%B2%A1%E6%9C%89%E5%88%99%E5%90%91%E9%A1%B5%2Fspan%20%E8%A6%81%22%5D%0A%20%20FREE%5B%22free%22%5D%20--%3E%20PUSH%5B%22%E5%8E%8B%E5%9B%9E%20class%20%E6%88%96%E5%90%88%E5%B9%B6%E9%82%BB%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>与 hazard：延迟释放的块仍占 class，直到真正 free。与 LSM：堆不是日志结构文件，但 thread cache 批量交还类似。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>元数据放块头则用户越界会毁链——这是安全课边界，本课点名。对齐与 size class 量化造成内碎片。本课不写利用分配器的 exploit。</p><p>最后一课：对象图的引用计数遇环不能只靠分配器 free。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 jemalloc/tcmalloc 源码当词条。内核 SLAB 与用户堆同族。GC 标记清除是另一策略，下一课只钉引用计数与环。</p><p>后课默认：堆 = size class + 页 span + 可选合并。对象寿命用引用计数时必须处理环。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分配器：边界标签、空闲链、size class/slab。</li><li>并发靠线程缓存与分中心堆。</li><li>引用计数的环是最后一课。</li><li>出处：Knuth 卷 1；Wilson et al., 1995；buddy 课。</li></ul>',9))])}const S=l(u,[["render",h]]);export{B as __pageData,S as default};
